macros.command:
(async () => {
  const scenes = game.scenes.contents;

  ui.notifications.info(`Gerando miniaturas para ${scenes.length} cenas...`);

  let atual = 0;

  for (const scene of scenes) {
    atual++;

    try {
      console.log(`Gerando thumbnail: ${scene.name}`);

      const thumb = await scene.createThumbnail();

      await scene.update({
        thumb: thumb.thumb
      });

      console.log(`OK - ${scene.name}`);
    } catch (err) {
      console.error(`Erro em ${scene.name}`, err);
    }
  }

  ui.notifications.info(`Concluído! ${atual} cenas processadas.`);
})();
